// Importez les modules Discord.js v14 nécessaires
const { Client, GatewayIntentBits, Events } = require('discord.js');

// Créez un objet de client Discord.js avec les intents requis
const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.MessageContent
  ]
});

// Connexion du client Discord.js au serveur
client.once(Events.Connected, () => {
  console.log('Connexion réussie au serveur Discord!');
});

// Écoute des événements de la commande "bannir"
client.on(Events.InteractionCreate, async interaction => {
  if (!interaction.isChatInputCommand() || interaction.commandName !== 'bannir') return;

  // Vérifiez si l'utilisateur possède les permissions requises pour bannir
  if (!interaction.member.permissions.has('BAN_MEMBERS')) {
    await interaction.reply({ content: 'Vous n'avez pas les permissions de bannir les membres du serveur!', ephemeral: true });
    return;
  }

  // Récupérez le membre cible à bannir
  const member = interaction.guild.members.cache.get(interaction.options.getMember('user').id);

  // Vérifiez si le membre cible existe dans le serveur
  if (!member) {
    await interaction.reply({ content: 'Le membre cible n\'existe pas dans le serveur!', ephemeral: true });
    return;
  }

  // Vérifiez si l'utilisateur possède les permissions requises pour bannir le membre cible
  if (!interaction.member.permissions.has('BAN_MEMBERS', { checkAdmin: true }) || !member.permissions.has('ViewChannel', { deny: true })) {
    await interaction.reply({ content: 'Vous n'avez pas les permissions de bannir ce membre du serveur!', ephemeral: true });
    return;
  }

  // Bannissez le membre cible avec une raison personnalisée
  try {
    await member.ban({ reason: `Commande "bannir" exécutée par ${interaction.user.tag}` });
    await interaction.reply({ content: `Le membre ${member.user.tag} a été banni avec succès!`, ephemeral: true });
  } catch (err) {
    console.error(err);
    await interaction.reply({ content: 'Une erreur est survenue lors du bannissement du membre!', ephemeral: true });
  }
});

// Connexion du client Discord.js au serveur
client.login(process.env.TOKEN);
