#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <SDL2/SDL.h>

#define SCREEN_WIDTH 800
#define SCREEN_HEIGHT 600

struct Snake {
    int x, y;
    int dir;
    struct Snake *next;
};

struct Food {
    int x, y;
};

// Fonction de dessin pour afficher les images du serpent et de la nourriture
void render(SDL_Renderer *renderer, struct Snake *snake, struct Food *food) {
    SDL_SetRenderDrawColor(renderer, 0, 0, 0, SDL_ALPHA_OPAQUE);
    SDL_RenderClear(renderer);

    for (struct Snake *s = snake; s != NULL; s = s->next) {
        SDL_Rect rect = { s->x, s->y, 20, 20 };
        SDL_SetRenderDrawColor(renderer, 255, 255, 255, SDL_ALPHA_OPAQUE);
        SDL_RenderFillRect(renderer, &rect);
    }

    SDL_Rect rect = { food->x, food->y, 20, 20 };
    SDL_SetRenderDrawColor(renderer, 255, 0, 0, SDL_ALPHA_OPAQUE);
    SDL_RenderFillRect(renderer, &rect);

    SDL_RenderPresent(renderer);
}

// Fonction de collision pour vérifier si la tête du serpent touche une autre entité
int collision(struct Snake *snake, struct Food *food) {
    return snake->x == food->x && snake->y == food->y;
}

// Fonction de création de la nourriture aléatoire
struct Food create_food(SDL_Renderer *renderer) {
    struct Food food;
    do {
        food.x = rand() % (SCREEN_WIDTH / 20) * 20 + 20;
        food.y = rand() % (SCREEN_HEIGHT / 20) * 20 + 20;
    } while (collision(NULL, &food));

    return food;
}

int main(int argc, char *argv[]) {
    SDL_Init(SDL_INIT_VIDEO);

    SDL_Window *window = SDL_CreateWindow(
        "Snake Game",
        SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
        SCREEN_WIDTH, SCREEN_HEIGHT,
        SDL_WINDOW_SHOWN
    );

    SDL_Renderer *renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    struct Snake snake = { SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2, 0, NULL };
    struct Snake *tail = &snake;

    struct Food food = create_food(renderer);

    bool running = true;
    SDL_Event event;

    while (running) {
        while (SDL_PollEvent(&event)) {
            switch (event.type) {
                case SDL_QUIT:
                    running = false;
                    break;
                case SDL_KEYDOWN:
                    switch (event.key.keysym.sym) {
                        case SDLK_LEFT:
                            if (snake.dir != 1)
                                snake.dir = -1;
                            break;
                        case SDLK_RIGHT:
                            if (snake.dir != -1)
                                snake.dir = 1;
                            break;
                        default:
                            break;
                    }
                    break;
            }
        }

        struct Snake *prev = NULL;
        struct Snake *curr = &snake;
        int moved = 0;

        while (curr != NULL) {
            if (curr->next == NULL) {
                curr->x += curr->dir;
                moved = 1;
            } else {
                prev->x = curr->x;
                prev->y = curr->y;
                prev = curr;
                curr = curr->next;
            }
        }

        if (collision(&snake, &food)) {
            struct Snake *new_tail = (struct Snake *)malloc(sizeof(struct Snake));
            new_tail->x = tail->x;
            new_tail->y = tail->y;
            new_tail->dir = tail->dir;
            new_tail->next = NULL;

            tail->next = new_tail;
            tail = new_tail;

            food = create_food(renderer);
        }

        if (moved) {
            if (snake.x < 0 || snake.x >= SCREEN_WIDTH ||
                snake.y < 0 || snake.y >= SCREEN_HEIGHT) {
                running = false;
            }
        }

        render(renderer, &snake, &food);
    }

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}
```

