```javascript
function checkPrime(arr) {
  // Vérifier que le tableau contienne exactement 5 nombres
  if (arr.length !== 5) {
    console.error('Le tableau doit contenir exactement 5 nombres.');
    return;
  }

  // Parcourir chaque nombre dans le tableau
  for (let I = 0; I < arr.length; i++) {
    const num = arr[i];

    // Vérifier que le nombre est un entier positif
    if (typeof num !== 'number' || !Number.isInteger(num) || num <= 1) {
      continue;
    }

    // Vérifier si le nombre est premier
    let isPrime = true;
    for (let j = 2; j <= Math.sqrt(num); j++) {
      if (num % j === 0) {
        isPrime = false;
        break;
      }
    }

    // Si le nombre est premier, l'imprimer sur la console
    if (isPrime) {
      console.log(`Le premier nombre premier trouvé est ${num}.`);
      return;
    }
  }
}

// Exemple d'utilisation
const myArr = [2, 3, 5, 7, 11];
checkPrime(myArr);
```

La fonction `checkPrime` prend un tableau d'entrée `arr` qui doit contenir exactement 5 nombres. Elle parcourt chaque nombre dans le tableau et vérifie si celui-ci est un nombre premier valide. Si un nombre premier est trouvé, la fonction imprime celui-ci sur la console et retourne. Si aucun nombre premier n'est trouvé dans le tableau, la fonction ne retourne rien. 

